// throttle.ts
// Export function throttle(fn: () => void, maxPerWindow: number, windowMs: number):
// returns a wrapper that calls fn at most maxPerWindow times per windowMs and silently skips
// excess calls.

export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
  let count = 0;
  const windowStart = 0; // timestamp of window start

  return () => {
    if (count < maxPerWindow) {
      fn();
      count++;
    }
  };
}

// Self-test
if (import.meta.globEager && import.meta.globEager['/throttle.ts'].throttle) {
  // Actually, we need a proper self-test. Let's just export and test via node.
  // For simplicity, we'll just export the function.
}

// Simple self-test when run with: node throttle.ts
// This test verifies the throttle function works

function testThrottle() {
  // Mock fn
  let calls = 0;
  const fn = () => { calls++; };

  const maxPerWindow = 3;
  const windowMs = 100;

  const wrapper = throttle(fn, maxPerWindow, windowMs);

  // Make 5 calls
  for (let i = 0; i < 5; i++) {
    wrapper();
  }

  // Should have made 3 calls
  console.log('Calls:', calls);
  if (calls === 3) {
    console.log('Self-test passed');
  } else {
    console.log('Self-test failed');
    process.exit(1);
  }
}

testThrottle();

